    12→  api_doc_url: "https://www.bybit.com/app/user/api-management",
    13→
    14→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    15→    const { method, path } = params;
    16→    const timestamp = params.timestamp;
    17→    const recvWindow = "5000";
    18→    // Bybit requires alphabetically sorted params for signature
    19→    const queryString = params.params
    20→      ? Object.entries(params.params).sort(([a], [b]) => a.localeCompare(b)).map(([k, v]) => `${k}=${v}`).join("&")
    21→      : "";
    22→    const prehash = timestamp + credentials.api_key + recvWindow + queryString;
    23→    const signature = createHmac("sha256", credentials.secret)
    24→      .update(prehash)
    25→      .digest("hex");
    26→
    27→    const url = queryString
    28→      ? `${BASE_URL}${path}?${queryString}`
    29→      : `${BASE_URL}${path}`;
    30→
    31→    return {
    32→      url,
    33→      headers: {
    34→        "X-BAPI-API-KEY": credentials.api_key,
    35→        "X-BAPI-SIGN": signature,
    36→        "X-BAPI-TIMESTAMP": timestamp,
    37→        "X-BAPI-RECV-WINDOW": recvWindow,
    38→        "Content-Type": "application/json",
    39→      },
    40→    };
    41→  },
    42→
    43→  async testConnection(credentials: Credentials): Promise<TestResult> {
    44→    const timestamp = Date.now().toString();
    45→    const path = "/v5/account/wallet-balance";
    46→    const signed = this.sign(credentials, { method: "GET", path, timestamp, params: { accountType: "UNIFIED" } });
    47→
    48→    const start = Date.now();
    49→    try {
    50→      const res = await fetch(signed.url, { method: "GET", headers: signed.headers, signal: AbortSignal.timeout(10_000) });
    51→      const latency_ms = Date.now() - start;
    52→      const json = (await res.json()) as { retCode?: number; retMsg?: string };
    53→      if (json.retCode === 0) return { success: true, latency_ms };
    54→      return { success: false, error: json.retMsg ?? `Error: ${json.retCode}`, latency_ms };
    55→    } catch (e) {
    56→      return { success: false, error: e instanceof Error ? e.message : "Network error", latency_ms: Date.now() - start };
    57→    }
    58→  },
    59→};
