     1→import { createHmac } from "node:crypto";
     2→import type { Exchange, Credentials, SignParams, SignedRequest } from "./types";
     3→import type { TestResult } from "../types";
     4→
     5→const BASE_URL = "https://api.lighter.xyz";
     6→
     7→export const lighterExchange: Exchange = {
     8→  id: "lighter",
     9→  name: "Lighter",
    10→  fields: ["api_key", "secret"],
    11→  referral_url: "https://lighter.xyz",
    12→  api_doc_url: "https://docs.lighter.xyz",
