    14→  sign(credentials: Credentials, params: SignParams): SignedRequest {
    15→    const { method, path, body } = params;
    16→    const timestamp = params.timestamp;
    17→    const prehash = timestamp + method + path + (body ?? "");
    18→    const signature = createHmac("sha256", credentials.secret)
    19→      .update(prehash)
    20→      .digest("hex");
    21→
    22→    return {
    23→      url: BASE_URL + path,
    24→      headers: {
    25→        "X-API-KEY": credentials.api_key,
    26→        "X-API-SIGNATURE": signature,
    27→        "X-API-TIMESTAMP": timestamp,
    28→        "Content-Type": "application/json",
    29→      },
    30→    };
    31→  },
    32→
    33→  async testConnection(credentials: Credentials): Promise<TestResult> {
    34→    const timestamp = Date.now().toString();
    35→    const path = "/api/v1/account";
